local root = vim.env.MOVIM_TOOLS_TEST_DIR .. '/ui-project'
vim.fn.mkdir(root, 'p')
local child = vim.fn.jobstart({ vim.v.progpath, '--embed', '--headless', '-u', vim.fn.getcwd() .. '/init.lua' }, { rpc = true, cwd = root })
assert(child > 0)
local function request(method, ...) return vim.rpcrequest(child, method, ...) end
local function execute(code, ...) return request('nvim_exec_lua', code, { ... }) end
local function wait(code, message)
  assert(vim.wait(5000, function() return execute(code) end), message .. ': ' .. vim.inspect(execute([[return {mode=vim.fn.mode(), line=vim.api.nvim_get_current_line(), messages=vim.api.nvim_exec2('messages',{output=true}).output}]])))
end
local ok, failure = pcall(function()
  request('nvim_ui_attach', 150, 42, { rgb = true })
  execute([[require('lazy').load({plugins={'nvim-lint'}}); vim.api.nvim_clear_autocmds({group='nvim-lint'})]])
  execute([[vim.cmd('edit test.js'); vim.api.nvim_buf_set_lines(0,0,-1,false,{''}); vim.g.disable_autoformat=true]])
  request('nvim_input', 'i')
  wait([[return vim.fn.mode() == 'i' and vim.fn.maparg('<Tab>','i',false,true).callback ~= nil]], 'Completion mappings did not attach')
  request('nvim_input', 'log')
  wait([[return vim.api.nvim_get_current_line() == 'log']], 'Abbreviation was not typed')
  request('nvim_input', '<Tab>')
  wait([[return vim.api.nvim_get_current_line() == 'console.log(value);']], 'Tab did not expand the log template')
  request('nvim_input', "'hello'")
  wait([[return vim.api.nvim_get_current_line() == "console.log('hello');"]], 'Typing did not replace template placeholder')
  request('nvim_input', '<Tab>')
  wait([[return vim.api.nvim_win_get_cursor(0)[2] == #vim.api.nvim_get_current_line()]], 'Tab did not reach the final template cursor')
  request('nvim_input', ' // finished<Esc>')
  wait([[return vim.api.nvim_get_current_line() == "console.log('hello'); // finished"]], 'Tab did not jump to final template position')
  print('PASS actual Tab expansion and placeholder navigation')
  execute([[require('luasnip').unlink_current(); vim.cmd('stopinsert'); vim.api.nvim_buf_set_lines(0,0,-1,false,{'prefix '}); vim.api.nvim_win_set_cursor(0,{1,6}); vim.cmd('startinsert!'); require('utils.clipboard_history').record({'clipboard ui'},'v')]])
  request('nvim_input', '<C-S-v>')
  wait([[return vim.bo.filetype == 'TelescopePrompt']], 'Clipboard shortcut did not open the picker')
  request('nvim_input', 'clipboard ui')
  wait([[local e=require('telescope.actions.state').get_selected_entry(); return e and e.value.lines[1] == 'clipboard ui']], 'Clipboard filter did not select copied text')
  request('nvim_input', '<CR>')
  wait([[return vim.bo.filetype == 'javascript' and vim.api.nvim_get_current_line() == 'prefix clipboard ui' and vim.fn.mode() == 'i']], 'Clipboard paste was not inserted at the original cursor')
  request('nvim_input', '!<Esc>')
  wait([[return vim.api.nvim_get_current_line() == 'prefix clipboard ui!']], 'Typing after clipboard paste resumed at wrong position')
  print('PASS clipboard picker filters and pastes at the original Insert cursor')
  execute([[vim.cmd('startinsert!')]])
  request('nvim_input', '<C-S-v>')
  wait([[return vim.bo.filetype == 'TelescopePrompt']], 'Clipboard picker did not reopen')
  request('nvim_input', '<Esc>')
  wait([[return vim.bo.filetype == 'javascript' and vim.fn.mode() == 'i']], 'Cancelling clipboard picker did not restore Insert mode')
  request('nvim_input', '<Esc>')
  wait([[return vim.fn.mode()=='n']], 'Clipboard cancellation did not finish')
  execute([[require('utils.clipboard_history').clear(); require('utils.clipboard_history').record({'delete this item'},'v'); require('utils.clipboard_history').record({'keep this item'},'v'); require('utils.clipboard_history').open(nil,true)]])
  wait([[return vim.bo.filetype == 'TelescopePrompt']], 'Clipboard delete test did not open')
  request('nvim_input', 'delete this item')
  wait([[local e=require('telescope.actions.state').get_selected_entry(); return e and e.value.lines[1]=='delete this item']], 'Clipboard delete selection did not settle')
  request('nvim_input', '<C-d>')
  wait([[return vim.bo.filetype == 'TelescopePrompt' and #require('utils.clipboard_history').items()==1]], 'Deleting clipboard item reimported it')
  request('nvim_input', '<C-x>')
  wait([[return vim.bo.filetype=='javascript' and #require('utils.clipboard_history').items()==0]], 'Clearing clipboard history failed')
  print('PASS clipboard cancel, deletion and clear')
  execute([[vim.api.nvim_buf_set_lines(0,0,-1,false,{'فارسی'}); vim.api.nvim_win_set_cursor(0,{1,0}); vim.cmd('normal! v$'); local original=vim.ui.select; vim.ui.select=function(items,opts,callback) for _,item in ipairs(items) do if item.abbreviation=='if' then callback(item); break end end end; require('utils.live_templates').pick(true); vim.ui.select=original]])
  wait([[local lines=vim.api.nvim_buf_get_lines(0,0,-1,false); return lines[1]=='if (condition) {' and lines[2] and lines[2]:find('فارسی',1,true) ~= nil]], 'Surround selection did not preserve Unicode text')
  print('PASS live templates surround selected Unicode text')
  request('nvim_input', '<Esc>')
  wait([[return vim.fn.mode()=='n']], 'Unicode surround did not leave Insert mode')
  execute([[require('luasnip').unlink_current(); vim.cmd('stopinsert'); vim.api.nvim_buf_set_lines(0,0,-1,false,{'first();','second();'}); vim.api.nvim_win_set_cursor(0,{1,0}); vim.cmd('normal! Vj'); local original=vim.ui.select; vim.ui.select=function(items,opts,callback) for _,item in ipairs(items) do if item.abbreviation=='if' then callback(item); break end end end; require('utils.live_templates').pick(true); vim.ui.select=original]])
  wait([[local text=table.concat(vim.api.nvim_buf_get_lines(0,0,-1,false),'\n'); return text:find('first();',1,true) and text:find('second();',1,true)]], 'Multiline surround lost selected text')
  print('PASS multiline template surround preserves both lines')
  request('nvim_input', '<Esc>')
  wait([[return vim.fn.mode()=='n']], 'Multiline surround did not leave Insert mode')
  execute([[require('luasnip').unlink_current(); vim.cmd('stopinsert'); vim.api.nvim_buf_set_lines(0,0,-1,false,{'abc first','def second'}); vim.api.nvim_win_set_cursor(0,{1,0}); vim.api.nvim_feedkeys(vim.api.nvim_replace_termcodes('<C-v>jl',true,false,true),'nx',false); require('utils.live_templates').pick(true)]])
  wait([[return vim.deep_equal(vim.api.nvim_buf_get_lines(0,0,-1,false),{'abc first','def second'})]], 'Blockwise surround removed unselected text')
  print('PASS blockwise template surround preserves buffer')
  request('nvim_input', '<Esc>')
  wait([[return vim.fn.mode()=='n']], 'Blockwise surround did not leave Visual mode')
  for _, kind in ipairs({ 'files', 'grep' }) do
    execute([[local kind=...; local path=vim.fn.getcwd()..'/preview-'..kind..'.txt'; vim.fn.writefile({'preview source '..kind,'second line'},path); local builtin=require('telescope.builtin'); local open=kind=='files' and builtin.find_files or builtin.live_grep; vim.g.movim_search_ready=false; open({cwd=vim.fn.getcwd(),default_text=kind=='files' and 'preview-files.txt' or 'preview source grep',_completion_callbacks={function(p) vim.g.movim_search_ready=p:get_selection()~=nil end}})]], kind)
    wait([[if vim.bo.filetype~='TelescopePrompt' then return false end; local p=require('telescope.actions.state').get_current_picker(vim.api.nvim_get_current_buf()); return p and p:get_selection() and p.preview_win and vim.api.nvim_win_is_valid(p.preview_win) and vim.api.nvim_buf_get_lines(vim.api.nvim_win_get_buf(p.preview_win),0,1,false)[1]:find('preview source',1,true)]], 'Search preview did not load: '..kind)
    wait([[return vim.fn.mode()=='i' and vim.g.movim_search_ready]], 'Search results did not finish loading: '..kind)
    request('nvim_input', '<C-e>')
    wait([[return vim.bo.buftype=='' and vim.api.nvim_buf_get_name(0):find('/preview%-') and vim.fn.mode()=='n']], 'Ctrl+E did not enter the real preview file: '..kind)
    request('nvim_input', 'ikeyboard <Esc><C-s>')
    wait([[return vim.fn.readfile(vim.api.nvim_buf_get_name(0))[1]:find('keyboard ',1,true)==1]], 'Typing and saving in preview failed: '..kind)
    request('nvim_input', '<C-e>')
    wait([[return vim.bo.filetype=='TelescopePrompt' and vim.fn.mode()=='i']], 'Ctrl+E did not return to search: '..kind)
    local position = execute([[local p=require('telescope.actions.state').get_current_picker(vim.api.nvim_get_current_buf()); return vim.api.nvim_win_get_position(p.preview_win)]])
    request('nvim_input_mouse', 'left', 'press', '', 0, position[1] + 1, position[2] + 3)
    request('nvim_input_mouse', 'left', 'release', '', 0, position[1] + 1, position[2] + 3)
    wait([[return vim.bo.buftype=='' and vim.api.nvim_buf_get_name(0):find('/preview%-') and vim.api.nvim_win_get_config(0).relative~='']], 'Clicking the preview did not activate the real editor: '..kind)
    wait([[return vim.fn.mode()=='n' and vim.api.nvim_win_get_cursor(0)[1]==2]], 'Preview click did not preserve the clicked line: '..kind)
    request('nvim_input', 'iclicked <Esc><C-s>')
    wait([[return vim.fn.readfile(vim.api.nvim_buf_get_name(0))[2]:find('clicked ',1,true)~=nil]], 'Clicked preview could not be edited and saved: '..kind)
    request('nvim_input', '<C-e>')
    wait([[return vim.bo.filetype=='TelescopePrompt' and vim.fn.mode()=='i']], 'Clicked preview did not return to search: '..kind)
    request('nvim_input', '<C-c>')
    wait([[return vim.bo.filetype~='TelescopePrompt' and vim.fn.mode()=='n']], 'Search did not close: '..kind)
    print('PASS '..kind..' preview keyboard and mouse editing saves actual file')
  end
end)
pcall(request, 'nvim_command', 'qa!')
pcall(vim.fn.jobstop, child)
pcall(vim.fn.jobwait, { child }, 2000)
assert(ok, failure)
print('PASS ui complete')
vim.cmd('qa!')
